function blocked(x,y,r=13){if(x<25+r||x>W-25-r||y<25+r||y>H-25-r)return true;return WORLD.buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}
